3	/**
4	 * Extracts code content from a react-markdown code element.
5	 * Handles the nested structure where code is passed as children.
6	 *
7	 * @param children - The children prop from react-markdown (typically a code element)
8	 * @returns The extracted code content as a string with trailing newline removed
9	 */
10	export const extractCodeContent = (children: ReactNode): string => {
11	  const codeElement = isValidElement(children) ? (children as ReactElement<{ children?: ReactNode }>) : null;
12	  return String(codeElement?.props.children || "").replace(/\n$/, "");
13	};
