17	export const CodeBlock = ({ children, className, node: _node, ...props }: CodeBlockProps) => {
18	  const { userGeneralSetting } = useAuth();
19	  const [copied, setCopied] = useState(false);
20	
21	  const codeElement = isValidElement(children) ? (children as ReactElement<{ className?: string }>) : null;
22	  const codeClassName = codeElement?.props.className || "";
23	  const codeContent = extractCodeContent(children);
24	  const language = extractLanguage(codeClassName);
25	
26	  // If it's a mermaid block, render with MermaidBlock component
27	  if (language === "mermaid") {
28	    return (
29	      <pre className="relative">
30	        <MermaidBlock className={cn(className)} {...props}>
31	          {children}
32	        </MermaidBlock>
33	      </pre>
34	    );
35	  }
36	
37	  const theme = getThemeWithFallback(userGeneralSetting?.theme);
38	  const resolvedTheme = resolveTheme(theme);
39	  const isDarkTheme = resolvedTheme.includes("dark");
40	
41	  // Dynamically load highlight.js theme based on app theme
42	  useEffect(() => {
43	    const dynamicImportStyle = async () => {
44	      // Remove any existing highlight.js style
45	      const existingStyle = document.querySelector("style[data-hljs-theme]");
46	      if (existingStyle) {
47	        existingStyle.remove();
48	      }
49	
50	      try {
51	        const cssModule = isDarkTheme
52	          ? await import("highlight.js/styles/github-dark-dimmed.css?inline")
53	          : await import("highlight.js/styles/github.css?inline");
54	
55	        // Create and inject the style
56	        const style = document.createElement("style");
57	        style.textContent = cssModule.default;
58	        style.setAttribute("data-hljs-theme", isDarkTheme ? "dark" : "light");
59	        document.head.appendChild(style);
60	      } catch (error) {
61	        console.warn("Failed to load highlight.js theme:", error);
62	      }
63	    };
64	
65	    dynamicImportStyle();
66	  }, [resolvedTheme, isDarkTheme]);
67	
68	  // Highlight code using highlight.js
69	  const highlightedCode = useMemo(() => {
70	    try {
71	      const lang = hljs.getLanguage(language);
72	      if (lang) {
73	        return hljs.highlight(codeContent, {
74	          language: language,
75	        }).value;
76	      }
77	    } catch {
78	      // Skip error and use default highlighted code.
79	    }
80	
81	    // Escape any HTML entities when rendering original content.
82	    return Object.assign(document.createElement("span"), {
83	      textContent: codeContent,
84	    }).innerHTML;
85	  }, [language, codeContent]);
