91	        await navigator.clipboard.writeText(codeContent);
92	        setCopied(true);
93	        setTimeout(() => setCopied(false), 2000);
94	      } else {
95	        // Fallback to copy-to-clipboard library for non-secure contexts
96	        const success = await copy(codeContent);
97	        if (success) {
98	          setCopied(true);
99	          setTimeout(() => setCopied(false), 2000);
100	        } else {
101	          console.error("Failed to copy code");
102	        }
103	      }
104	    } catch (err) {
105	      // If native API fails, try fallback
106	      console.warn("Native clipboard failed, using fallback:", err);
107	      const success = await copy(codeContent);
108	      if (success) {
109	        setCopied(true);
110	        setTimeout(() => setCopied(false), 2000);
111	      } else {
112	        console.error("Failed to copy code:", err);
113	      }
114	    }
115	  };
116	
117	  return (
118	    <pre className="relative my-2 rounded-lg border border-border bg-muted/20 overflow-hidden">
119	      {/* Header with language label and copy button */}
120	      <div className="flex items-center justify-between px-2 py-1 border-b border-border bg-muted/30">
121	        <span className="text-xs text-foreground select-none">{language || "text"}</span>
122	        <button
123	          onClick={handleCopy}
124	          className={cn(
125	            "inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-xs",
126	            "transition-colors duration-200",
127	            "hover:bg-accent active:scale-95",
128	            copied ? "text-primary" : "text-muted-foreground hover:text-foreground",
129	          )}
130	          aria-label={copied ? "Copied" : "Copy code"}
131	          title={copied ? "Copied!" : "Copy code"}
132	        >
133	          {copied ? (
134	            <>
135	              <CheckIcon className="w-3.5 h-3.5" />
136	              <span>Copied</span>
137	            </>
138	          ) : (
139	            <>
140	              <CopyIcon className="w-3.5 h-3.5" />
141	              <span>Copy</span>
142	            </>
143	          )}
144	        </button>
145	      </div>
146	
147	      {/* Code content */}
148	      <div className="overflow-x-auto">
149	        <code
